import pandas as pd
from datetime import timedelta

def run(inputs: dict) -> dict:
    events = inputs["app_events"].copy()

    events = events.sort_values(["user_id", "event_ts", "event_id"], kind="mergesort")

    results = []
    threshold = timedelta(minutes=30)

    for user_id, grp in events.groupby("user_id", sort=False):
        session_num = 0
        open_session = None  # dict with keys: start, last_activity, end, event_count, heartbeat_count

        def finalize(sess):
            nonlocal session_num
            session_num += 1
            results.append({
                "user_id": user_id,
                "session_num": session_num,
                "session_start": sess["start"],
                "session_end": sess["end"],
                "event_count": sess["event_count"],
                "heartbeat_count": sess["heartbeat_count"],
            })

        for _, row in grp.iterrows():
            ts = row["event_ts"]
            etype = row["event_type"]

            if etype in ("view", "click", "logout"):
                if open_session is None:
                    open_session = {
                        "start": ts,
                        "last_activity": ts,
                        "end": ts,
                        "event_count": 1,
                        "heartbeat_count": 0,
                    }
                else:
                    delta = ts - open_session["last_activity"]
                    if delta > threshold:
                        # close current session, start new one
                        finalize(open_session)
                        open_session = {
                            "start": ts,
                            "last_activity": ts,
                            "end": ts,
                            "event_count": 1,
                            "heartbeat_count": 0,
                        }
                    else:
                        open_session["event_count"] += 1
                        open_session["last_activity"] = ts
                        open_session["end"] = ts

                if etype == "logout":
                    finalize(open_session)
                    open_session = None

            elif etype == "heartbeat":
                if open_session is not None:
                    delta = ts - open_session["last_activity"]
                    if delta <= threshold:
                        open_session["event_count"] += 1
                        open_session["heartbeat_count"] += 1
                    # else dropped
                # else dropped

        if open_session is not None:
            finalize(open_session)

    columns = ["user_id", "session_num", "session_start", "session_end",
               "event_count", "heartbeat_count"]

    if results:
        out = pd.DataFrame(results, columns=columns)
    else:
        out = pd.DataFrame(columns=columns)

    return {"user_sessions": out}
